def comprimir_repeticiones(texto: str) -> str:
    if not texto:
        return ""

    resultado = []
    actual_char = texto[0]
    contador = 1

    for char in texto[1:]:
        if char == actual_char:
            contador += 1
        else:
            resultado.append(f"{actual_char}{contador}")
            actual_char = char
            contador = 1

    # Añadir el último grupo
    resultado.append(f"{actual_char}{contador}")

    return "".join(resultado)

def planoar(datos: list) -> list:
    """
    Aplana una lista que puede contener listas y tuplas anidadas a cualquier profundidad.
    Devuelve una nueva lista con los elementos no list/tuple en el mismo orden.
    """
    resultado = []

    def _flatten(obj):
        # Si es lista o tupla, procesamos sus elementos recursivamente
        if isinstance(obj, (list, tuple)):
            for item in obj:
                _flatten(item)
        else:
            # Cualquier otro tipo se añade sin modificar
            resultado.append(obj)

    # Se asegura de que 'datos' sea una lista; si no lo es, se envuelve en una lista.
    if not isinstance(datos, list):
        datos = [datos]

    _flatten(datos)
    return resultado

def parsear_ventas(texto: str) -> list[dict]:
    import csv
    import io

    # Dividir el texto en líneas, eliminando los saltos de línea
    lineas = texto.splitlines()

    # Omitir líneas vacías o que solo contengan espacios
    lineas_filtradas = [linea for linea in lineas if linea.strip() != '']

    # Si no hay contenido, devolver lista vacía
    if not lineas_filtradas:
        return []

    # Verificar la cabecera
    cabecera = lineas_filtradas[0].strip()
    esperada = "fecha,producto,cantidad,precio"
    if cabecera != esperada:
        raise ValueError("Cabecera incorrecta")

    resultado = []

    # Procesar cada línea de datos
    for linea in lineas_filtradas[1:]:
        # Utilizar el lector CSV para manejar comillas y campos con comas
        try:
            filas = next(csv.reader(io.StringIO(linea)))
        except Exception:
            raise ValueError("Error al interpretar la línea")

        # Cada fila debe tener exactamente 4 campos
        if len(filas) != 4:
            raise ValueError("Fila con número incorrecto de campos")

        fecha, producto, cantidad_str, precio_str = filas

        # Validar cantidad: debe ser un entero no negativo
        try:
            cantidad = int(cantidad_str)
        except ValueError:
            raise ValueError("cantidad no es un entero")
        if cantidad < 0:
            raise ValueError("cantidad negativa")

        # Validar precio: debe ser convertible a float
        try:
            precio = float(precio_str)
        except ValueError:
            raise ValueError("precio no es un número")

        resultado.append({
            "fecha": fecha,
            "producto": producto,
            "cantidad": cantidad,
            "precio": precio
        })

    return resultado

from collections import OrderedDict


class CacheLRU:
    def __init__(self, capacidad: int):
        if capacidad < 0:
            raise ValueError("Capacidad negativa")
        self.capacidad = capacidad
        self._datos = OrderedDict()

    def get(self, clave):
        if clave not in self._datos:
            return None
        # Marcar como recientemente usado
        self._datos.move_to_end(clave)
        return self._datos[clave]

    def put(self, clave, valor):
        if self.capacidad == 0:
            return
        if clave in self._datos:
            # Actualizar y marcar como usado
            self._datos[clave] = valor
            self._datos.move_to_end(clave)
        else:
            # Nueva clave
            if len(self._datos) >= self.capacidad:
                # Descartar el menos recientemente usado
                self._datos.popitem(last=False)
            self._datos[clave] = valor

    def __len__(self):
        return len(self._datos)
